python3 -c "
import json
from collections import defaultdict, Counter

with open('$FILE', 'r') as f:
    outer = json.load(f)

inner = json.loads(outer['result'])
experiments = inner['data']['experiments']

# Servers and GPU assignments
print('=== SERVERS AND GPU ASSIGNMENTS ===')
server_map = defaultdict(list)
for eid, e in experiments.items():
    server = e.get('server')
    if not server:
        spec = e.get('spec', {})
        if isinstance(spec, dict):
            server = spec.get('server')
    if server:
        gpu_ids = e.get('gpu_ids')
        if not gpu_ids:
            spec = e.get('spec', {})
            if isinstance(spec, dict):
                gpu_ids = spec.get('gpu_ids')
        server_map[server].append((eid, e.get('status'), gpu_ids))

for server, exps in sorted(server_map.items()):
    print(f'  Server: {server}')
    # Show unique GPU assignments
    gpu_set = set()
    for eid, status, gpu_ids in exps:
        if gpu_ids:
            if isinstance(gpu_ids, list):
                for g in gpu_ids:
                    gpu_set.add(str(g))
            else:
                gpu_set.add(str(gpu_ids))
    print(f'    GPU IDs used: {sorted(gpu_set) if gpu_set else \"N/A\"}')
    # Show active experiments on this server
    active = [(eid, status, gpu_ids) for eid, status, gpu_ids in exps if status in ('RUNNING', 'PREPARING', 'QUEUED', 'ALLOCATED')]
    if active:
        print(f'    Active experiments ({len(active)}):')
        for eid, status, gpu_ids in active:
            print(f'      {eid}: {status}, gpu_ids={gpu_ids}')
    print()

# Conclusion breakdown for DONE
print('=== DONE EXPERIMENTS BY CONCLUSION ===')
conclusion_counts = Counter()
for eid, e in experiments.items():
    if e.get('status') == 'DONE':
        conclusion_counts[e.get('conclusion', 'unknown')] += 1
for c, n in sorted(conclusion_counts.items()):
    print(f'  {c}: {n}')

# Baseline data
print()
print('=== BASELINE DATA ===')
baseline = inner['data'].get('baseline', {})
if baseline:
    print(f'  {json.dumps(baseline, indent=2)[:500]}')
else:
    print('  No baseline data')
"

